<?php
if(!founder_story_schema_ready()){echo '<section class="journey-panel"><h2>Final-copy approval setup is being upgraded</h2><p>Founder stories remain private until the migration and approval workflow are ready. No review notification is sent during setup.</p></section>';return;}
$storyWorkflow=founder_story_workflow((int)$submission['id']);$storyReviews=[];$storyDeliveries=[];
if($storyWorkflow){$query=db()->prepare('SELECT * FROM founder_story_reviews WHERE founder_id=? ORDER BY round_no DESC');$query->execute([$submission['id']]);$storyReviews=$query->fetchAll();$query=db()->prepare('SELECT channel,state,error_code,accepted_at FROM founder_story_deliveries WHERE review_id=?');$query->execute([$storyWorkflow['current_review_id']]);$storyDeliveries=$query->fetchAll();}
?>
<section class="journey-panel reader-space"><span class="writer-kicker">Final-copy approval</span><h2>Founder review · <?=(int)($storyWorkflow['rounds_used']??0)?> of 3</h2>
<p>Prepare and link the private draft, then send its exact version to the founder’s own email and WhatsApp. General permission and editorial approval do not replace this step. An approved version still needs your publication decision.</p>
<?php if($submission['associated_post_id']):?><p><a class="wbtn" href="<?=e(url('/write/edit/'.$submission['associated_post_id']))?>">Open linked story draft</a></p><?php endif;?>
<?php if($storyWorkflow):?><p><strong>Status:</strong> <?=e(ucfirst(str_replace('_',' ',$storyWorkflow['state'])))?></p><?php endif;?>
<?php foreach($storyDeliveries as$delivery):?><p><?=e(ucfirst($delivery['channel']))?> · <?=e($delivery['state']==='accepted'?'Accepted by provider (delivery/read receipt not confirmed)':ucfirst($delivery['state']))?><?=$delivery['error_code']?' · '.e(str_replace('_',' ',$delivery['error_code'])):''?></p><?php endforeach;?>
<?php if(!$storyWorkflow||($storyWorkflow['state']!=='discarded'&&(int)$storyWorkflow['rounds_used']<3)):?>
<form method="post" action="<?=e(url('/write/founder-stories/'.$submission['id'].'/request'))?>" class="journey-form"><?=csrf_field()?>
<div class="field"><label for="story-founder-email">Founder’s own email</label><input id="story-founder-email" type="email" name="founder_email" maxlength="254" value="<?=e($storyWorkflow['email']??($submission['submission_type']==='founder'?$submission['submitter_email']:''))?>" <?=$storyWorkflow?'readonly':''?> required></div>
<div class="field"><label for="story-founder-wa">Founder’s WhatsApp number</label><input id="story-founder-wa" type="tel" name="founder_whatsapp" placeholder="+254…" pattern="\+[1-9][0-9]{7,14}" maxlength="20" value="<?=e($storyWorkflow['whatsapp']??'')?>" <?=$storyWorkflow?'readonly':''?> required></div>
<div class="field"><label for="story-contact-evidence">Contact verification and WhatsApp permission record</label><input id="story-contact-evidence" name="contact_evidence" maxlength="500" value="<?=e($storyWorkflow['contact_evidence']??'')?>" required><small>Use a private correspondence or consent reference. A nominator’s details are not the founder’s identity.</small></div>
<div class="field"><label for="story-review-days">Response window after both providers accept the notifications (days)</label><input id="story-review-days" type="number" name="response_days" min="1" max="30" value="14" required></div>
<label class="journey-check"><input type="checkbox" name="contact_confirmed" value="1" required><span>I verified that both contacts belong to the founder.</span></label>
<label class="journey-check"><input type="checkbox" name="whatsapp_optin" value="1" required><span>The founder agreed to receive these review notifications by email and WhatsApp, with the permission record above.</span></label>
<label class="journey-check"><input type="checkbox" name="send_review_ack" value="1" required><span>Send this saved draft for founder approval. A changed version uses the next review round and invalidates the previous link.</span></label>
<button class="wbtn primary" type="submit">Send saved version for review</button></form>
<?php else:?><p>No additional review rounds are available. The private audit record is retained; an unapproved or discarded story cannot be published.</p><?php endif;?>
<?php if($storyWorkflow&&$storyWorkflow['state']==='pending'):?><form method="post" action="<?=e(url('/write/founder-stories/'.$submission['id'].'/retry'))?>" class="journey-form reader-space"><?=csrf_field()?><p>Fix provider settings before retrying blocked notifications. Accepted notifications are not resent. An uncertain attempt requires a provider-record check.</p><label class="journey-check"><input type="checkbox" name="provider_checked" value="1"><span>I checked any uncertain attempt with the provider and confirmed it was not accepted.</span></label><button class="wbtn" type="submit">Retry eligible notifications</button></form><?php endif;?>
<p class="journey-help">Declined, expired or three-times-unapproved stories are automatically discarded from publication. Private audit records remain. If notifications cannot be accepted by both providers within 30 days, the unapproved story is archived with a delivery-failure reason.</p>
<?php foreach($storyReviews as$storyReview):?><details class="reader-space"><summary>Review <?=(int)$storyReview['round_no']?> · <?=e(ucfirst(str_replace('_',' ',$storyReview['state'])))?></summary><p>Requested <?=e(reader_utc_label($storyReview['created_at']))?><?=$storyReview['expires_at']?' · Due '.e(reader_utc_label($storyReview['expires_at'])):''?></p><?php if($storyReview['response_note']):?><p><?=nl2br(e($storyReview['response_note']))?></p><?php endif;?>
<?php if($storyReview['proposed_json']):$proposal=json_decode($storyReview['proposed_json'],true,32,JSON_THROW_ON_ERROR);?><h3>Founder’s proposed copy</h3><h4><?=e($proposal['title'])?></h4><p><?=e($proposal['standfirst'])?></p><div><?=sanitize_html($proposal['content_html'])?></div><?php if($storyWorkflow['state']==='changes_requested'&&(int)$storyWorkflow['current_review_id']===(int)$storyReview['id']):?><form method="post" action="<?=e(url('/write/founder-stories/'.$submission['id'].'/apply-edits'))?>"><?=csrf_field()?><button class="wbtn" type="submit">Import edits into private draft for editorial review</button></form><?php endif;?><?php endif;?></details><?php endforeach;?>
</section>
